//! Migrations and database provisioning.

mod manifest;
mod migrate;
mod settings;

use std::collections::BTreeSet;

use futures_util::{StreamExt, stream};
use resysto_surrealdb::{Config, Db, SchemaFile};

use crate::migrate::{chain, migrate};
use crate::settings::Settings;

const MASTER_DB: &str = "__master";

/// Tenants migrated at the same time by `migrate_up`.
const TENANT_CONCURRENCY: usize = 4;

// `MASTER` and `TENANT`, generated by `build.rs`.
include!(concat!(env!("OUT_DIR"), "/lanes.rs"));

struct Lane {
    schema: &'static [SchemaFile],
    manifests: &'static [ManifestFile],
}

#[derive(Debug)]
struct ManifestFile {
    path: &'static str,
    toml: &'static str,
}

#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error(transparent)]
    Db(#[from] resysto_surrealdb::Error),
    #[error("schema file {path} builds an index CONCURRENTLY")]
    ConcurrentIndex { path: &'static str },
    #[error("manifest {path}: {reason}")]
    InvalidManifest { path: &'static str, reason: String },
    #[error("manifest {path} changed after it was applied")]
    ManifestChanged { path: &'static str },
    #[error("manifest {path} is older than a manifest already applied")]
    OutOfOrder { path: &'static str },
    #[error("manifest {path}, {section} step {step} failed")]
    Step {
        path: &'static str,
        section: &'static str,
        step: usize,
        source: Box<dyn std::error::Error + Send + Sync>,
    },
    #[error(transparent)]
    Config(#[from] resysto_config::Error),
    #[error("database does not exist")]
    MissingDatabase,
    #[error("{} tenant migrations failed:{}", .0.len(), failures(.0))]
    Tenants(Vec<(String, Error)>),
}

impl From<surrealdb::Error> for Error {
    fn from(error: surrealdb::Error) -> Self {
        Self::Db(error.into())
    }
}

fn failures(failed: &[(String, Error)]) -> String {
    failed
        .iter()
        .map(|(database, error)| format!("\n  {database}: {}", chain(error)))
        .collect()
}

/// Creates the master database if missing and applies the `master` lane. Safe to repeat.
pub async fn provision_master(db: &Db) -> Result<(), Error> {
    provision(db, MASTER_DB, &MASTER, &[]).await
}

/// Creates `database` if missing and applies the `tenant` lane. Safe to repeat.
pub async fn provision_tenant(db: &Db, database: &str) -> Result<(), Error> {
    provision(db, database, &TENANT, &[("access_key", db.verifying_key())]).await
}

pub async fn migrate_up() -> Result<(), Error> {
    let Settings { db, auth } = resysto_config::load()?;
    let db = Db::connect(Config {
        endpoint: db.endpoint,
        namespace: db.namespace,
        username: db.migrator_user,
        password: db.migrator_password,
        signing_key: auth.signing_key,
        verifying_key: auth.verifying_key,
    })
    .await?;
    migrate_up_from(&db, MASTER_DB, TENANT_CONCURRENCY).await?;
    println!("migrations applied");
    Ok(())
}

async fn migrate_up_from(db: &Db, master: &str, concurrency: usize) -> Result<(), Error> {
    provision(db, master, &MASTER, &[]).await?;
    let mut response = db
        .system_session(master)
        .await?
        .query(
            "SELECT VALUE db_name FROM tenant WHERE state IN ['ready', 'suspended'];
             RETURN object::keys((INFO FOR NS).databases);",
        )
        .await?
        .check()?;
    let tenants: Vec<String> = response.take(0)?;
    let databases: Vec<String> = response.take(1)?;
    let databases: BTreeSet<String> = databases.into_iter().collect();
    let mut failed: Vec<(String, Error)> = stream::iter(tenants)
        .map(|database| {
            let exists = databases.contains(&database);
            async move {
                // Opening a session would create the missing database empty.
                let result = if exists {
                    migrate_tenant(db, &database).await
                } else {
                    Err(Error::MissingDatabase)
                };
                (database, result)
            }
        })
        .buffer_unordered(concurrency.max(1))
        .filter_map(|(database, result)| async move { result.err().map(|error| (database, error)) })
        .collect()
        .await;
    if failed.is_empty() {
        return Ok(());
    }
    failed.sort_by(|a, b| a.0.cmp(&b.0));
    Err(Error::Tenants(failed))
}

async fn migrate_tenant(db: &Db, database: &str) -> Result<(), Error> {
    let session = db.system_session(database).await?;
    migrate(&session, &TENANT, &[("access_key", db.verifying_key())]).await
}

async fn provision(
    db: &Db,
    database: &str,
    lane: &Lane,
    params: &[(&str, &str)],
) -> Result<(), Error> {
    db.define_database(database).await?;
    let session = db.system_session(database).await?;
    migrate(&session, lane, params).await
}

#[cfg(test)]
pub(crate) mod tests {
    use surrealdb::types::{RecordId, Uuid, Value};

    use super::*;

    // Test-only key pair.
    const SIGNING_KEY: &str = "-----BEGIN PRIVATE KEY-----
MIGHAgEAMBMGByqGSM49AgEGCCqGSM49AwEHBG0wawIBAQQgCcu34KTFnm0J5qWJ
AxhAcHSbqFj+B/am0htHlDufqWihRANCAASN/BWdDI7GaVVD6HAh20C4ZzJSHSsz
9htiM2MVKHWJFnxAy4GKb6YFXGV6KEDsrn5MQIa7TTsyRDnIcCjQztXz
-----END PRIVATE KEY-----
";
    const VERIFYING_KEY: &str = "-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEjfwVnQyOxmlVQ+hwIdtAuGcyUh0r
M/YbYjNjFSh1iRZ8QMuBim+mBVxleihA7K5+TECGu007MkQ5yHAo0M7V8w==
-----END PUBLIC KEY-----
";

    pub(crate) async fn connect() -> Db {
        let port = std::env::var("SURREAL_PORT").unwrap_or_else(|_| "18000".into());
        Db::connect(Config {
            endpoint: format!("ws://127.0.0.1:{port}"),
            namespace: "resysto-dev".into(),
            username: "ns_migrator".into(),
            password: "migrator".into(),
            signing_key: SIGNING_KEY.into(),
            verifying_key: VERIFYING_KEY.into(),
        })
        .await
        .unwrap()
    }

    async fn new_tenant(db: &Db) -> String {
        let name = format!("t_test_{}", Uuid::new_v4().simple());
        provision_tenant(db, &name).await.unwrap();
        name
    }

    async fn info(db: &Db, database: &str) -> Value {
        let session = db.system_session(database).await.unwrap();
        session.query("INFO FOR DB").await.unwrap().take(0).unwrap()
    }

    #[test]
    fn every_lane_passes_the_load_checks() {
        for lane in [&MASTER, &TENANT] {
            migrate::check_schema(lane).unwrap();
            manifest::load(lane).unwrap();
        }
    }

    #[tokio::test]
    async fn a_provisioned_tenant_accepts_record_sessions() {
        let db = connect().await;
        let tenant = new_tenant(&db).await;
        let user = RecordId::new("account", Uuid::new_v7());

        let session = db.record_session(&tenant, user.clone()).await.unwrap();

        let auth: Option<RecordId> = session
            .query("RETURN $auth")
            .await
            .unwrap()
            .take(0)
            .unwrap();
        assert_eq!(auth, Some(user));
    }

    #[tokio::test]
    async fn migrate_up_covers_ready_and_suspended_tenants_and_reports_each_failure() {
        let db = connect().await;
        let id = Uuid::new_v4().simple();
        let master = format!("t_test_master_{id}");
        let ready = format!("t_test_ready_{id}");
        let suspended = format!("t_test_suspended_{id}");
        let missing = format!("t_test_missing_{id}");
        let deleted = format!("t_test_deleted_{id}");
        for database in [&ready, &suspended] {
            db.define_database(database).await.unwrap();
        }
        provision(&db, &master, &MASTER, &[]).await.unwrap();
        db.system_session(&master)
            .await
            .unwrap()
            .query(
                "CREATE tenant SET db_name = $ready, state = 'ready';
                 CREATE tenant SET db_name = $suspended, state = 'suspended';
                 CREATE tenant SET db_name = $missing, state = 'ready';
                 CREATE tenant SET db_name = $deleted, state = 'deleted';",
            )
            .bind(("ready", ready.clone()))
            .bind(("suspended", suspended.clone()))
            .bind(("missing", missing.clone()))
            .bind(("deleted", deleted.clone()))
            .await
            .unwrap()
            .check()
            .unwrap();

        let result = migrate_up_from(&db, &master, 2).await;

        let Err(Error::Tenants(failed)) = result else {
            panic!("{result:?}")
        };
        let failed: Vec<&str> = failed.iter().map(|(name, _)| name.as_str()).collect();
        assert_eq!(failed, [missing.as_str()]);
        for database in [&ready, &suspended] {
            let user = RecordId::new("account", Uuid::new_v7());
            db.record_session(database, user).await.unwrap();
        }
    }

    #[tokio::test]
    async fn provisioning_again_leaves_the_schema_as_it_was() {
        let db = connect().await;
        let tenant = new_tenant(&db).await;
        let before = info(&db, &tenant).await;
        provision_tenant(&db, &tenant).await.unwrap();
        assert_eq!(info(&db, &tenant).await, before);
    }
}
